@Test
public void testThrowableMessage() throws Exception {
    // #43398
    BuildException be = new BuildException("oops", new Location("build.xml", 1, 0));
    assertEquals("build.xml:1: oops" + StringUtils.LINE_SEP, msg(be, false));
    be = ProjectHelper.addLocationToBuildException(be, new Location("build.xml", 2, 0));
    assertEquals("build.xml:2: The following error occurred while executing this line:" + StringUtils.LINE_SEP + "build.xml:1: oops" + StringUtils.LINE_SEP, msg(be, false));
    be = ProjectHelper.addLocationToBuildException(be, new Location("build.xml", 3, 0));
    assertEquals("build.xml:3: The following error occurred while executing this line:" + StringUtils.LINE_SEP + "build.xml:2: The following error occurred while executing this line:" + StringUtils.LINE_SEP + "build.xml:1: oops" + StringUtils.LINE_SEP, msg(be, false));
    Exception x = new Exception("problem") {

        public void printStackTrace(PrintWriter w) {
            w.println("problem");
            w.println("  at p.C.m");
        }
    };
    assertEquals("problem" + StringUtils.LINE_SEP + "  at p.C.m" + StringUtils.LINE_SEP, msg(x, false));
    be = new BuildException(x, new Location("build.xml", 1, 0));
    assertEquals("build.xml:1: problem" + StringUtils.LINE_SEP + "  at p.C.m" + StringUtils.LINE_SEP, msg(be, false));
    be = ProjectHelper.addLocationToBuildException(be, new Location("build.xml", 2, 0));
    assertEquals("build.xml:2: The following error occurred while executing this line:" + StringUtils.LINE_SEP + "build.xml:1: problem" + StringUtils.LINE_SEP + "  at p.C.m" + StringUtils.LINE_SEP, msg(be, false));
}

