    ds.addDefaultExcludes();
    ds.ensureNonPatternSetsReady();
    File f = new File(".svn");
    TokenizedPath p = new TokenizedPath(f.getAbsolutePath());
    assertTrue(ds.contentsExcluded(p));
}

