    m.setFrom("*foo");
    m.setTo("*plonk");
    assertNull("Shouldn\'t match *foo", m.mapFileName("bar.baz"));
    String[] result = m.mapFileName("bar.foo");
    assertNotNull("Should match *.foo", result);
    assertEquals("only one result for bar.foo", 1, result.length);
